import {createQuiz} from './quiz.js?v=5';
import {mountLab,LABS} from './labs.js?v=4';
import {mountWalkthrough,cleanWalkProgress} from './walkthrough.js?v=5';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='ec2k2-study-v2';let D,lessons,questions,byId,extra,Q,store,storageOK=true,timer,toastTimer;
const emptyStore=()=>({version:2,answers:{},bookmarks:[],understood:[],walks:{},session:null});
try{store=JSON.parse(localStorage.getItem(KEY))||emptyStore();if(store.version!==2||!store.answers||!Array.isArray(store.bookmarks)||!Array.isArray(store.understood))store=emptyStore()}catch{store=emptyStore();storageOK=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify(store))}catch{storageOK=false;$('#save-status').textContent='Storage unavailable · export to keep progress'}}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800)}
const lessonBy=id=>lessons.find(l=>l.id===id);const answered=()=>questions.filter(q=>store.answers[q.id]&&!store.answers[q.id].needsReview);const correct=()=>answered().filter(q=>store.answers[q.id].correct);const stats=()=>`<div class="stats-row"><div class="stat"><strong>${answered().length}<small class="small"> / 400</small></strong><span>IB400 QUESTIONS ATTEMPTED</span></div><div class="stat"><strong>${answered().length?Math.round(correct().length/answered().length*100):0}%</strong><span>LATEST ANSWER ACCURACY</span></div><div class="stat"><strong>${store.understood.length}<small class="small"> / ${lessons.reduce((s,l)=>s+l.concepts.length,0)}</small></strong><span>CONCEPTS SELF-CHECKED</span></div><div class="stat"><strong>${questions.filter(q=>store.answers[q.id]&&(!store.answers[q.id].correct||store.answers[q.id].needsReview)).length}</strong><span>QUESTIONS TO REVISIT</span></div></div>`;
function heroArt(){return `<div class="hero-art"><svg viewBox="0 0 440 310" aria-label="Illustration of two intersecting economic curves"><defs><pattern id="grid" width="31" height="31" patternUnits="userSpaceOnUse"><path d="M31 0H0V31" fill="none" stroke="#dce4cc" stroke-width=".7"/></pattern></defs><rect width="440" height="310" fill="url(#grid)"/><path d="M57 40V248H395" fill="none" stroke="#7b9671"/><path d="M77 76L370 222" fill="none" stroke="#8a6eb1" stroke-width="3"/><path d="M82 223L367 72" fill="none" stroke="#6d99bb" stroke-width="3"/><path d="M222 42V248" stroke="#83a36c" stroke-dasharray="6 5" stroke-width="2"/><circle cx="222" cy="148" r="17" fill="#d9edaa"/><circle cx="222" cy="148" r="5" fill="#35533a"/><text x="365" y="244" font-family="serif" font-style="italic" fill="#8a6eb1">IS</text><text x="372" y="68" font-family="serif" font-style="italic" fill="#6d99bb">LM</text><text x="230" y="51" font-family="serif" fill="#83a36c">FE</text><text x="46" y="31" font-family="serif" font-style="italic" fill="#58734d">r</text><text x="401" y="252" font-family="serif" font-style="italic" fill="#58734d">Y</text><rect x="260" y="105" width="135" height="34" rx="7" fill="#fff" stroke="#dbe4d0"/><text x="274" y="126" font-size="11" font-family="sans-serif" fill="#6a825e">Every line has a reason.</text></svg><div class="hero-note">Change an assumption. Follow the consequences.</div></div>`}

function migrateContent(){if(!D.revision||store.contentRevision===D.revision)return;const changed=new Set(D.revisedQuestionIds||[]);let count=0;for(const id of changed){if(store.answers[id]){store.answers[id].needsReview=true;count++}}if(store.session){let affected=false;for(const id of changed){if(store.session.ids.includes(id)&&store.session.responses[id]!==undefined){delete store.session.responses[id];delete store.session.confidence?.[id];affected=true}}if(affected){store.session.finished=false;store.session.review=false;store.session.end=null}}store.contentRevision=D.revision;save();if(count)setTimeout(()=>toast(`${count} revised questions need another attempt. Your other progress is retained.`),100)}
function auditSection(){if(!D.audit)return '';const grouped={};for(const row of D.audit.coverage||[])(grouped[row.file]??=[]).push(row);const linkFor=id=>{const l=lessons.find(l=>l.concepts.some(c=>c.id===id));const c=l?.concepts.find(c=>c.id===id);return c?`<a class="inline-link" href="#decoded/${l.id}/${id}">${E(c.title)}</a>`:E(id)};return `<div class="coverage-section"><p class="eyebrow">SOURCE AUDIT · ${E(D.audit.date)}</p><h2>Checked against the actual source pages</h2><p>All ${D.audit.questionsReviewed} question stems, answer keys and five-choice explanations were reviewed. The map below accounts for substantive content and identifies administrative or repeated pages separately. Annotated companions were treated as study notes and checked against the original course material.</p><p class="small">${E(D.audit.summary||'')}</p>${Object.entries(grouped).map(([file,rows])=>`<details class="source-card"><summary><strong>${E(file)}</strong><span class="small"> · ${rows.length} mapped entries</span></summary><div class="table-wrap" style="margin-top:15px"><table class="coverage-table"><thead><tr><th>PDF pages</th><th>Source topic</th><th>Decoded coverage</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.pages)}</td><td>${E(r.topic)}</td><td>${r.status==='noninstructional'?'<span class="small">Administration, overview or repeated material</span>':(r.conceptIds||[]).map(linkFor).join('<br>')}${r.note?`<p class="small">${E(r.note)}</p>`:''}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}</div>`}

function home(){return `<section class="hero"><div><p class="eyebrow">YOUR EC2102 STUDY SPACE</p><h1>Understand what<br>moves the <em>economy.</em></h1><p class="intro">Build intuition, work through the logic, then put it to the test. The entire supplied lecture sequence, connected in one place.</p><div class="actions"><a href="#decoded" class="primary">Explore Decoded <span>↗</span></a><a href="#ib400" class="secondary">Practise with IB400 <span>→</span></a></div></div>${heroArt()}</section>${stats()}<div class="section-head"><h2>Four ways to make the course yours.</h2><p>Learn the mechanism, then test it.</p></div><div class="path-grid">${[
 ['ib400','01','PRACTISE & DIAGNOSE','IB400','400 original questions with five choices each. From tutorial foundations to exam reasoning and challenging edge cases.','Find out what you understand'],
 ['st100','02','COMBINE & CHALLENGE','S&T100','100 harder synthesis questions with six choices each. Combine shocks, identify binding constraints and reason backwards from the outcome.','Push beyond the familiar'],
 ['decoded','03','EXPLORE & UNDERSTAND','EC2102 Decoded','12 connected chapters and 148 guided concepts. Derive equations, build graphs, and work through both directions and edge cases.','Make every curve mean something'],
 ['recaps','04','REVISIT & RECONSTRUCT','Wong Wei Kang Recaps',`${extra.recaps.length} revision MCQs covering every requested part of all ten supplied tutorials, with explanations for every option.`,'Rebuild the tutorial reasoning']
].map(([route,num,tag,name,desc,cta])=>`<a href="#${route}" class="path-card"><span class="tag">${tag}</span><span class="card-number">${num}</span><h2>${name}</h2><p>${desc}</p><strong class="inline-link">${cta} ↗</strong></a>`).join('')}</div><div class="note">Your existing IS–LM–FE and AD–AS policy lab now lives in <a class="inline-link" href="#decoded/islm">Decoded’s IS–LM–FE chapter</a>. This expanded EC2K2 replaces the former homepage.</div>`}
function lessonCards(list=lessons){return list.map(l=>{const i=lessons.indexOf(l),done=l.concepts.filter(c=>store.understood.includes(c.id)).length,n=questions.filter(q=>q.lesson===l.id).length;return `<a class="lesson-card" href="#decoded/${l.id}"><span class="index">${String(i+1).padStart(2,'0')} / DECODED</span><h3>${E(l.title)}</h3><p>${E(l.subtitle)}</p><div class="lesson-card-bottom"><span>${l.concepts.length} concepts · ${n} questions</span><span>${done} / ${l.concepts.length} checked ↗</span></div><div class="bar"><i style="width:${done/l.concepts.length*100}%"></i></div></a>`}).join('')}
function decoded(){return `<p class="eyebrow">EC2102 DECODED</p><h1>From assumptions<br>to understanding.</h1><p class="intro">Work through every derivation and graph one step at a time. Predict what happens next, explain why it happens, then test both directions and the boundaries of the model.</p><div class="note">Lecture Topics 1–9, all three Goods Market decks, initial wealth and growth-rate supplements, plus the two-period consumer–worker tutorial. <a class="inline-link" href="#coverage">See the source coverage map ↗</a></div><div class="search-row"><input id="lesson-search" type="search" placeholder="Find a concept, equation or chapter…" aria-label="Search Decoded"></div><div class="section-head"><h2>The course, connected</h2><p>${lessons.reduce((s,l)=>s+l.concepts.length,0)} guided concept walkthroughs · ${Object.values(LABS).flat().length} experiments</p></div><div class="course-grid" id="course-grid">${lessonCards()}</div>`}
function bindDecoded(){$('#lesson-search').addEventListener('input',e=>{const s=e.target.value.toLowerCase();$('#course-grid').innerHTML=lessonCards(lessons.filter(l=>JSON.stringify(l).toLowerCase().includes(s)))||'<p class="small">No matching concepts.</p>'})}
function lesson(id,concept){const l=lessonBy(id);if(!l)return decoded();const c=l.concepts.find(c=>c.id===concept)||l.concepts[0],index=l.concepts.indexOf(c),done=store.understood.includes(c.id);return `<a href="#decoded" class="breadcrumb-back">← All chapters</a><div class="lesson-heading"><div><p class="eyebrow">CHAPTER ${String(lessons.indexOf(l)+1).padStart(2,'0')} · EC2102 DECODED</p><h1>${E(l.title)}</h1><p class="intro">${E(l.subtitle)}</p></div><a href="#ib400/${l.id}" class="primary">Practise this chapter ↗</a></div><div class="lesson-layout"><nav class="concept-nav" aria-label="Concepts in this chapter">${l.concepts.map((x,i)=>`<button data-concept="${x.id}" class="${x===c?'active':''}"><b class="${store.understood.includes(x.id)?'done':''}">${store.understood.includes(x.id)?'✓':String(i+1).padStart(2,'0')}</b>${E(x.title)}</button>`).join('')}</nav><div class="concept-body"><article class="concept-panel"><p class="eyebrow">CONCEPT ${index+1} OF ${l.concepts.length}</p><h2>${E(c.title)}</h2><p class="explain">${E(c.explain)}</p><section class="walkthrough" id="guided-walkthrough" aria-label="Guided derivation and graph walkthrough"></section><details class="concept-reference"><summary>Quick reference · formula, cases and worked example</summary>${c.formula?`<div class="formula">${E(c.formula)}</div>`:''}<h3>The mechanism</h3><ol class="mechanism">${c.steps.map(s=>`<li>${E(s)}</li>`).join('')}</ol><div class="cases"><div class="case"><strong>↑ The increase case</strong>${E(c.increase)}</div><div class="case down"><strong>↓ The decrease case</strong>${E(c.decrease)}</div></div><div class="edge"><h4>When the usual conclusion changes</h4>${E(c.edge)}</div><div class="example"><p class="eyebrow">WORK IT THROUGH</p>${E(c.example)}</div><div class="check"><p class="eyebrow">EXPLAIN IT WITHOUT LOOKING</p><p>${E(c.check.prompt)}</p><details><summary>Compare your explanation</summary><p>${E(c.check.answer)}</p></details></div><p class="source-inline">${l.source.map(s=>`${E(s.file)} · PDF pp ${E(s.pages)}`).join('<br>')}</p></details></article><div class="concept-actions"><button class="secondary mark-button ${done?'done':''}" id="mark-concept">${done?'✓ Self-checked':'I can explain this'}</button><a class="secondary" href="#ib400/${l.id}/${c.id}">Test this concept ↗</a>${index<l.concepts.length-1?`<a class="primary" href="#decoded/${l.id}/${l.concepts[index+1].id}">Next concept →</a>`:`<a class="primary" href="#decoded">All chapters →</a>`}</div><section class="lab-panel" id="chapter-lab"></section></div></div>`}
function experimentFor(lesson,concept){
 const groups=[
  ['labour','supply',['time-budget','leisure-foc','nonlabor-income','wage-effects','aggregate-supply']],
  ['labour','labour-market',['labor-demand','labor-demand-algebra','implicit-function','labor-equilibrium','labor-shocks']],
  ['labour','unemployment',['unemployment','natural-okun']],
  ['investment','loanable',['investment-equilibrium','investment-crowding','is-derivation','is-shifts']],
  ['assets','fisher',['assets-fisher']],
  ['assets','growth',['assets-growth','assets-elasticity']],
  ['islm','slopes',['lm-algebra','lm-slope','vertical-lm','liquidity-trap']],
  ['classical','rbc',['rbc-shocks','rbc-transmission','classical-fiscal','rbc-evaluation']],
  ['islm','policy',['demand-recessions','keynesian-policy','stabilization','oil-shocks','classical-money']],
  ['phillips','hysteresis',['hysteresis']]
 ];const match=groups.find(g=>g[2].includes(concept));return match?[match[0],match[1]]:[lesson,undefined]
}
function bindLesson(id,concept){const l=lessonBy(id);if(!l){bindDecoded();return}const c=l.concepts.find(c=>c.id===concept)||l.concepts[0];document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>location.hash=`decoded/${l.id}/${b.dataset.concept}`);$('#mark-concept').onclick=()=>{const n=store.understood.indexOf(c.id);if(n<0)store.understood.push(c.id);else store.understood.splice(n,1);save();const el=$('#mark-concept');el.classList.toggle('done',n<0);el.textContent=n<0?'✓ Self-checked':'I can explain this';document.querySelector(`[data-concept="${c.id}"] b`).textContent=n<0?'✓':String(l.concepts.indexOf(c)+1).padStart(2,'0');toast(n<0?'Concept self-check saved':'Concept returned to your study list')};mountWalkthrough($('#guided-walkthrough'),c.id,{store,save});mountLab($('#chapter-lab'),...experimentFor(id,c.id))}
function coverage(){return `<p class="eyebrow">COURSE MAP & SOURCES</p><h1>Know what is covered.<br>Know what is assumed.</h1><p class="intro">The study bank and Decoded follow the supplied EC2102 lecture decks and tutorials. Source references use PDF page numbers.</p><div class="note"><strong>Coverage boundary</strong> · The supplied set now includes all ten tutorial question papers and their answer files. Wong Wei Kang Recaps maps every requested tutorial part to revision MCQs. The earlier lecture-page audit is preserved below with its original date. Difficulty labels are study-design judgments, not official exam classifications.</div><div class="coverage-section"><h2>How to use the three levels</h2><p>Tutorial questions test direct definitions, formulas and single mechanisms. Exam questions combine calculations, curves and assumptions. Challenge questions test counterexamples, limiting cases and model comparisons. These difficulty labels are study-design judgments, not official NUS classifications. The bank is original and is not a prediction of exam questions or format.</p><p>The concept checks and “I can explain this” markers are self-assessments, not proof of mastery. Use the mistake queue and try explaining each answer without the notes.</p></div><div class="table-wrap"><table class="coverage-table"><thead><tr><th>Chapter</th><th>Concepts</th><th>Tutorial</th><th>Exam</th><th>Challenge</th><th>Total</th></tr></thead><tbody>${lessons.map(l=>{const q=questions.filter(q=>q.lesson===l.id);return `<tr><td><a href="#decoded/${l.id}">${E(l.title)} ↗</a></td><td>${l.concepts.length}</td>${['Tutorial','Exam','Challenge'].map(d=>`<td>${q.filter(q=>q.difficulty===d).length}</td>`).join('')}<td>${q.length}</td></tr>`}).join('')}<tr><th>Total</th><th>${lessons.reduce((s,l)=>s+l.concepts.length,0)}</th>${['Tutorial','Exam','Challenge'].map(d=>`<th>${questions.filter(q=>q.difficulty===d).length}</th>`).join('')}<th>${questions.length}</th></tr></tbody></table></div><div class="coverage-section"><h2>Source and concept index</h2><p>Explanations and questions are original paraphrases grounded in the course material. Original lecture PDFs and recordings are not redistributed. Model equations in the experiments use transparent teaching calibrations.</p>${lessons.map(l=>`<article class="source-card"><h3>${E(l.title)}</h3>${l.source.map(s=>`<p>${E(s.file)} · PDF pp ${E(s.pages)}</p>`).join('')}<div class="coverage-concepts">${l.concepts.map(c=>`<a href="#decoded/${l.id}/${c.id}">${E(c.title)} · ${questions.filter(q=>q.concept===c.id).length} MCQs</a>`).join('')}</div></article>`).join('')}</div>${Q.recapMap()}${auditSection()}<div class="coverage-section"><h2>Model boundaries that matter</h2><p>Individual labour supply and saving responses can be ambiguous. Aggregate slopes are maintained assumptions. The fixed-price Keynesian fiscal lab holds FE fixed; the Classical fiscal lesson allows the wealth effect to shift labour supply and FE. Horizontal fixed-price SRAS and upward-sloping misperceptions SRAS are different models. The liquidity-trap floor is on the nominal rate, not the real rate. Hysteresis changes the fixed-natural-rate benchmark.</p><p>The simulations use illustrative parameters. They do not estimate the economy or forecast adjustment time. Long-run growth and open-economy models are excluded because the course introduction assigns them to EC3102.</p></div><div class="note">Study progress stays in this browser. Export and import are available in the top bar. The website is public. Your browser-local progress is not shared with other visitors. Independent study aid, not an official NUS resource.</div>`}
function render(scroll=true){clearInterval(timer);Q?.stop();let [page,id,cid]=(location.hash.slice(1)||'home').split('/');if(page==='lab'||page==='guide'||page==='sources'||page==='quiz'){location.replace(page==='quiz'?'#ib400':page==='sources'?'#coverage':'#decoded/islm');return}if(page==='question'&&byId[Number(id)]){Q.start([Number(id)],Q.bankOf(byId[Number(id)]),'practice',0,true);return}const bankPages=['ib400','st100','recaps'],active=page==='session'?Q.sessionBank(store.session):page,titles={home:'Your study space',ib400:'IB400',st100:'S&T100',recaps:'Wong Wei Kang Recaps',decoded:'EC2102 Decoded',session:Q.title(active),coverage:'Course map & sources'};$('#breadcrumb').textContent=titles[page]||titles.home;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===active));$('#main').innerHTML=page==='decoded'?(id?lesson(id,cid):decoded()):bankPages.includes(page)?Q.lobby(page,id,cid):page==='session'?Q.view():page==='coverage'?coverage():home();if(page==='decoded')id?bindLesson(id,cid):bindDecoded();if(bankPages.includes(page))Q.bindLobby();if(page==='session')Q.bindSession();if(scroll)window.scrollTo({top:0,behavior:'instant'});document.title=`EC2K2 · ${titles[page]||'Understand the economy'}`;}
$('#export-progress').onclick=()=>{const blob=new Blob([JSON.stringify({...store,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EC2K2-study-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup downloaded')};
$('#import-progress').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8000000)throw Error('Backup is too large');const x=JSON.parse(await file.text());if(x.version!==2||typeof x.answers!=='object'||!Array.isArray(x.bookmarks)||!Array.isArray(x.understood))throw Error('Not an EC2K2 progress backup');const clean=emptyStore();for(const[id,a]of Object.entries(x.answers)){if(byId[id]&&Number.isInteger(a.choice)&&a.choice>=0&&a.choice<byId[id].choices.length)clean.answers[id]={choice:a.choice,correct:a.choice===byId[id].answer,confidence:['guessed','unsure','confident'].includes(a.confidence)?a.confidence:'unsure',attempts:Math.max(1,Number(a.attempts)||1),firstCorrect:!!a.firstCorrect,needsReview:!!a.needsReview,time:Number(a.time)||Date.now()}}clean.bookmarks=x.bookmarks.filter(id=>byId[id]);const concepts=new Set(lessons.flatMap(l=>l.concepts.map(c=>c.id)));clean.understood=[...new Set(x.understood.filter(id=>concepts.has(id)))];clean.walks=cleanWalkProgress(x.walks,concepts);clean.session=Q.cleanSession(x.session);clean.contentRevision=x.contentRevision;store=clean;migrateContent();save();render(false);toast('Study progress imported')}catch(err){toast('Import failed. '+err.message)}finally{e.target.value=''}};
try{const responses=await Promise.all([fetch('data.json?v=5'),fetch('banks.json?v=5')]);if(responses.some(r=>!r.ok))throw Error('Course content could not be loaded');[D,extra]=await Promise.all(responses.map(r=>r.json()));lessons=D.lessons;questions=D.questions;if(!Array.isArray(lessons)||!Array.isArray(questions)||!Array.isArray(extra.st)||!Array.isArray(extra.recaps))throw Error('Course data format is invalid');const allQuestions=[...questions,...extra.st,...extra.recaps];byId=Object.fromEntries(allQuestions.map(q=>[q.id,q]));Q=createQuiz({getStore:()=>store,save,toast,render,lessons,allQuestions,extra});store.session=Q.cleanSession(store.session);if(!storageOK)$('#save-status').textContent='Storage unavailable · use Export';migrateContent();window.addEventListener('hashchange',()=>render());render()}catch(err){$('#main').innerHTML=`<div class="empty"><h1>Unable to load the course</h1><p>${E(err.message)}</p><button class="primary" onclick="location.reload()">Try again</button></div>`;console.error(err)}
